12	// TestDestroySuccess 成功销毁全部剩余量：数量、视图、历史与保留字段。
13	func TestDestroySuccess(t *testing.T) {
14		s, now := fixedStore(t)
15		mustRegister(t, s, "P", "4.250", "张三", "实验室A")
16	
17		at := now.Add(2 * time.Hour)
18		got, err := s.Destroy(DestroyInput{
19			SampleID: " P ", Operator: " 张三 ", Location: " 实验室A ",
20			At: at, Reason: " 实验结束按规程销毁 ",
21		})
22		if err != nil {
23			t.Fatalf("destroy: %v", err)
24		}
25		if got.Remaining != "0.000" {
26			t.Fatalf("销毁后剩余量应为 0.000, got %s", got.Remaining)
27		}
28		if got.InitialQty != "4.250" {
29			t.Fatalf("初始量应保留, got %s", got.InitialQty)
30		}
31		// 持有人和地点保留为销毁前的最后记录。
32		if got.Holder != "张三" || got.Location != "实验室A" {
33			t.Fatalf("销毁不应改变持有人地点: %+v", got)
34		}
35		if got.Destruction == nil {
36			t.Fatalf("已销毁样品查询应带销毁记录")
37		}
38		d := got.Destruction
39		if d.Operator != "张三" || d.Location != "实验室A" ||
40			d.Reason != "实验结束按规程销毁" || d.Qty != "4.250" || !d.At.Equal(at) {
41			t.Fatalf("销毁记录内容错误: %+v", d)
42		}
43		if got.PendingTransfer != nil {
44			t.Fatalf("销毁样品不应有待确认交接")
45		}
46	
47		// 历史末尾追加一次销毁事件，原有历史保留。
48		if len(got.History) != 2 {
49			t.Fatalf("应在原历史后追加一次销毁事件, got %d 条", len(got.History))
50		}
51		last := got.History[len(got.History)-1]
52		if last.Kind != "destroy" || !last.Time.Equal(at) ||
53			last.Holder != "张三" || last.Location != "实验室A" {
54			t.Fatalf("销毁历史事件错误: %+v", last)
55		}
56		if got.History[0].Kind != "register" {
57			t.Fatalf("原有保管历史应保留: %+v", got.History)
58		}
59	
60		// 重新查询结果一致。
61		again, err := s.GetSample("P")
62		if err != nil {
63			t.Fatal(err)
64		}
65		if again.Destruction == nil || again.Destruction.Qty != "4.250" || again.Remaining != "0.000" {
66			t.Fatalf("重新查询销毁信息错误: %+v", again)
67		}
68	}
