70	// TestDestroyDistinguishesFromSplitExhaustion 剩余量为零时必须能区分
71	// “分装用尽”和“已销毁”。
72	func TestDestroyDistinguishesFromSplitExhaustion(t *testing.T) {
73		s, _ := fixedStore(t)
74		mustRegister(t, s, "P", "1.000", "h", "l")
75		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "C", Qty: "1.000"}}}); err != nil {
76			t.Fatal(err)
77		}
78		exhausted, _ := s.GetSample("P")
79		if exhausted.Remaining != "0.000" {
80			t.Fatalf("前置条件：剩余量应为 0.000")
81		}
82		if exhausted.Destruction != nil {
83			t.Fatalf("分装用尽的样品不应有销毁记录: %+v", exhausted.Destruction)
84		}
85	
86		// 子样有剩余量，销毁后带销毁记录。
87		destroyed, err := s.Destroy(DestroyInput{
88			SampleID: "C", Operator: "h", Location: "l",
89			At: time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC), Reason: "过期",
90		})
91		if err != nil {
92			t.Fatalf("destroy: %v", err)
93		}
94		if destroyed.Remaining != "0.000" || destroyed.Destruction == nil {
95			t.Fatalf("销毁后应能通过销毁记录区分: %+v", destroyed)
96		}
97	
98		// 未销毁样品没有销毁记录。
99		fresh := mustRegister(t, s, "Q", "3.000", "h", "l")
100		if fresh.Destruction != nil {
101			t.Fatalf("未销毁样品不应有销毁记录")
102		}
103	}
