105	func TestDestroyValidation(t *testing.T) {
106		s, now := fixedStore(t)
107		mustRegister(t, s, "P", "1.000", "张三", "实验室A")
108	
109		base := func() DestroyInput {
110			return DestroyInput{
111				SampleID: "P", Operator: "张三", Location: "实验室A",
112				At: now.Add(time.Hour), Reason: "废弃",
113			}
114		}
115		cases := []struct {
116			name string
117			mut  func(DestroyInput) DestroyInput
118			want error
119		}{
120			{"空白编号", func(i DestroyInput) DestroyInput { i.SampleID = "  "; return i }, ErrInvalid},
121			{"空白操作人", func(i DestroyInput) DestroyInput { i.Operator = " "; return i }, ErrInvalid},
122			{"空白地点", func(i DestroyInput) DestroyInput { i.Location = "\t"; return i }, ErrInvalid},
123			{"空白原因", func(i DestroyInput) DestroyInput { i.Reason = ""; return i }, ErrInvalid},
124			{"零时间", func(i DestroyInput) DestroyInput { i.At = time.Time{}; return i }, ErrInvalid},
125			{"早于登记历史", func(i DestroyInput) DestroyInput { i.At = now.Add(-time.Second); return i }, ErrInvalid},
126			{"持有人不匹配", func(i DestroyInput) DestroyInput { i.Operator = "李四"; return i }, ErrConflict},
127			{"地点不匹配", func(i DestroyInput) DestroyInput { i.Location = "实验室B"; return i }, ErrConflict},
128		}
129		for _, c := range cases {
130			t.Run(c.name, func(t *testing.T) {
131				if _, err := s.Destroy(c.mut(base())); !errors.Is(err, c.want) {
132					t.Fatalf("want %v, got %v", c.want, err)
133				}
134			})
135		}
136	
137		// 销毁时间恰好等于已有历史时间可以接受（相同时间允许）。
138		if _, err := s.Destroy(func() DestroyInput {
139			i := base()
140			i.At = now // 与登记历史同一时刻
141			return i
142		}()); err != nil {
143			t.Fatalf("销毁时间与历史时间相同应允许, got %v", err)
144		}
145	}
