328	// TestDestroyParentChildIndependent 父样与子样的销毁各自独立。
329	func TestDestroyParentChildIndependent(t *testing.T) {
330		s, _ := fixedStore(t)
331		mustRegister(t, s, "P", "10.000", "张三", "A")
332		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
333			{ID: "C", Qty: "4.000"},
334		}}); err != nil {
335			t.Fatal(err)
336		}
337		// 父样剩余 6.000，销毁父样不动子样。
338		at := time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
339		p, err := s.Destroy(DestroyInput{
340			SampleID: "P", Operator: "张三", Location: "A", At: at, Reason: "r",
341		})
342		if err != nil {
343			t.Fatalf("destroy parent: %v", err)
344		}
345		if p.Remaining != "0.000" || p.Destruction == nil || p.Destruction.Qty != "6.000" {
346			t.Fatalf("父样销毁视图错误: %+v", p)
347		}
348		if len(p.Children) != 1 || p.Children[0] != "C" {
349			t.Fatalf("销毁应保留子样列表: %+v", p.Children)
350		}
351		c, _ := s.GetSample("C")
352		if c.Destruction != nil || c.Remaining != "4.000" || c.ParentID != "P" {
353			t.Fatalf("销毁父样不能改变已分出的子样: %+v", c)
354		}
355	
356		// 子样仍可独立流转并销毁；销毁子样不再扣减父样。
357		c2, err := s.Handover(HandoverInput{
358			TransferID: "TC", SampleID: "C",
359			FromHolder: "张三", FromLocation: "A",
360			ToHolder: "李四", ToLocation: "B", HandedOverAt: at.Add(time.Hour),
361		})
362		if err != nil {
363			t.Fatalf("未销毁子样应能继续交接: %v", err)
364		}
365		if c2.Confirmed {
366			t.Fatalf("子样交接应处于待确认")
367		}
368		if _, err := s.Confirm(ConfirmInput{"TC", "李四", "B", at.Add(2 * time.Hour)}); err != nil {
369			t.Fatal(err)
370		}
371		cd, err := s.Destroy(DestroyInput{
372			SampleID: "C", Operator: "李四", Location: "B",
373			At: at.Add(3 * time.Hour), Reason: "用尽销毁",
374		})
375		if err != nil {
376			t.Fatalf("destroy child: %v", err)
377		}
378		if cd.Destruction.Qty != "4.000" || cd.Remaining != "0.000" {
379			t.Fatalf("子样销毁视图错误: %+v", cd)
380		}
381		p2, _ := s.GetSample("P")
382		if p2.Remaining != "0.000" || p2.Destruction == nil || p2.Destruction.Qty != "6.000" {
383			t.Fatalf("销毁子样不得再扣减父样: %+v", p2)
384		}
385	}
