387	// TestDestroyPersistsAcrossReopen 重开后销毁信息、剩余量、操作限制与
388	// 幂等判断继续有效。
389	func TestDestroyPersistsAcrossReopen(t *testing.T) {
390		dir := t.TempDir()
391		path := filepath.Join(dir, "destroy.json")
392	
393		s, err := Open(path)
394		if err != nil {
395			t.Fatal(err)
396		}
397		clock := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
398		s.now = func() time.Time { return clock }
399		mustRegister(t, s, "P", "3.125", "张三", "A")
400		at := clock.Add(time.Hour)
401		first, err := s.Destroy(DestroyInput{
402			SampleID: "P", Operator: "张三", Location: "A", At: at, Reason: "污染",
403		})
404		if err != nil {
405			t.Fatal(err)
406		}
407	
408		s2, err := Open(path)
409		if err != nil {
410			t.Fatal(err)
411		}
412		got, err := s2.GetSample("P")
413		if err != nil {
414			t.Fatal(err)
415		}
416		if got.Remaining != "0.000" || got.InitialQty != "3.125" {
417			t.Fatalf("重开后数量错误: %+v", got)
418		}
419		if got.Destruction == nil || got.Destruction.Operator != "张三" ||
420			got.Destruction.Location != "A" || got.Destruction.Reason != "污染" ||
421			got.Destruction.Qty != "3.125" || !got.Destruction.At.Equal(at) {
422			t.Fatalf("重开后销毁信息应保留: %+v", got.Destruction)
423		}
424		if len(got.History) != len(first.History) ||
425			got.History[len(got.History)-1].Kind != "destroy" {
426			t.Fatalf("重开后销毁历史应保留: %+v", got.History)
427		}
428	
429		// 重开后重复提交相同信息仍幂等。
430		again, err := s2.Destroy(DestroyInput{
431			SampleID: "P", Operator: " 张三 ", Location: "A", At: at, Reason: "污染",
432		})
433		if err != nil {
434			t.Fatalf("重开后相同销毁请求应幂等返回: %v", err)
435		}
436		if len(again.History) != len(got.History) {
437			t.Fatalf("幂等重复不得追加历史")
438		}
439		// 改任一项仍拒绝；分装与新交接仍被限制。
440		if _, err := s2.Destroy(DestroyInput{
441			SampleID: "P", Operator: "张三", Location: "A", At: at.Add(time.Minute), Reason: "污染",
442		}); !errors.Is(err, ErrConflict) {
443			t.Fatalf("重开后销毁幂等判断应继续生效, got %v", err)
444		}
445		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "C", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
446			t.Fatalf("重开后已销毁样品仍不得分装, got %v", err)
447		}
448		if _, err := s2.Handover(HandoverInput{
449			TransferID: "TR-X", SampleID: "P",
450			FromHolder: "张三", FromLocation: "A",
451			ToHolder: "李四", ToLocation: "B", HandedOverAt: at.Add(time.Hour),
452		}); !errors.Is(err, ErrConflict) {
453			t.Fatalf("重开后已销毁样品仍不得发起新交接, got %v", err)
454		}
455	}
456	
457	// TestDestroyLegacyDataWithoutDestruction 旧数据中没有销毁信息的样品一律
458	// 视为未销毁，即使剩余量为零也不能推断为销毁。
459	func TestDestroyLegacyDataWithoutDestruction(t *testing.T) {
460		dir := t.TempDir()
461		path := filepath.Join(dir, "legacy.json")
462		regAt := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
463		legacy := ledger{
464			Version: 1,
465			Samples: map[string]*sampleRecord{
466				"OLD": {
467					ID:        "OLD",
468					Initial:   1000,
469					Remaining: 0, // 旧数据：分装用尽但没有销毁信息
470					Holder:    "h",
471					Location:  "l",
472					Children:  []string{},
473					History: []historyRecord{{
474						Kind: "register", Time: regAt, Holder: "h", Location: "l",
475					}},
476					// 没有 Destroyed 字段
477				},
478			},
479			Transfers: map[string]*transferRecord{},
480		}
481		raw, err := json.MarshalIndent(&legacy, "", "  ")
482		if err != nil {
483			t.Fatal(err)
484		}
485		if err := os.WriteFile(path, raw, 0o600); err != nil {
486			t.Fatal(err)
487		}
488	
489		s, err := Open(path)
490		if err != nil {
491			t.Fatal(err)
492		}
493		got, err := s.GetSample("OLD")
494		if err != nil {
495			t.Fatal(err)
496		}
497		if got.Remaining != "0.000" {
498			t.Fatalf("前置条件：剩余量应为 0.000, got %s", got.Remaining)
499		}
500		if got.Destruction != nil {
501			t.Fatalf("旧数据无销毁信息时不得推断为已销毁: %+v", got.Destruction)
502		}
503		// 视为未销毁且剩余量为零：销毁请求按冲突处理，而不是幂等返回。
504		if _, err := s.Destroy(DestroyInput{
505			SampleID: "OLD", Operator: "h", Location: "l",
506			At: regAt.Add(time.Hour), Reason: "r",
507		}); !errors.Is(err, ErrConflict) {
508			t.Fatalf("旧零剩余量样品销毁应 ErrConflict, got %v", err)
509		}
510	}
511	
512	// TestDestroyRejectedKeepsState 各类拒绝都不得改变数量、状态、历史。
513	func TestDestroyRejectedKeepsState(t *testing.T) {
514		s, _ := fixedStore(t)
515		mustRegister(t, s, "P", "1.500", "张三", "实验室A")
516		before, _ := s.GetSample("P")
517		at := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
518	
519		try := func(in DestroyInput) {
520			t.Helper()
521			if _, err := s.Destroy(in); err == nil {
522				t.Fatalf("应拒绝: %+v", in)
523			}
524		}
525		try(DestroyInput{SampleID: "P", Operator: "李四", Location: "实验室A", At: at, Reason: "r"})
526		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "X", At: at, Reason: "r"})
527		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "实验室A", At: time.Time{}, Reason: "r"})
528		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "实验室A", At: at, Reason: " "})
529		try(DestroyInput{SampleID: " ", Operator: "张三", Location: "实验室A", At: at, Reason: "r"})
530	
531		after, _ := s.GetSample("P")
532		if after.Remaining != before.Remaining || after.Holder != before.Holder ||
533			after.Location != before.Location || after.Destruction != nil ||
534			len(after.History) != len(before.History) {
535			t.Fatalf("被拒绝的销毁改动了状态: before=%+v after=%+v", before, after)
536		}
537	}
